# 64i_overlap_check_multiday.R
#
# Widened version of 64h_source_overlap_check.R — same fully-automated
# method (fingerprint matching, structured-metadata comparison, NO manual
# reading/coding of any row, per PJ 7 Sep: "no manual coding from me [...]
# means the checks can be replicated"), run across a SAMPLE of days rather
# than one, to test whether the 2019-11-05 finding (four whole debates
# present in ParlSpeech but entirely absent from Odell) is a one-off or a
# systematic pattern across the Odell-covered era.
#
# Sample: 12 days, one drawn from each of the parliaments/years spanning
# 1988-2019 (the Odell/ParlSpeech overlap window), picked as the first
# Wednesday sitting day on record in Odell for that year (Wednesday chosen
# for a consistent, arbitrary, non-cherry-picked rule).
#
# OUTPUT: console only.

suppressMessages({library(dplyr); library(readr); library(stringr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))

fingerprint <- function(x) x |> tolower() |> str_replace_all("[^a-z0-9]", "") |> str_sub(1, 120)

odell_full <- readRDS(file.path(WKBD_ROOT, "sources_raw/hansard_speeches_evanodell_1979_2020/hansard-speeches-v301.rds")) |>
  mutate(date = as.Date(date))
parl_full  <- readRDS(file.path(PROJECT, "data/dataverse_files/Corp_HouseOfCommons_V2.rds")) |>
  mutate(date = as.Date(date))

# Pick one Wednesday sitting day per calendar year, 1989-2019 (first Wednesday
# in Odell's own date list each year that ALSO has ParlSpeech rows — an
# objective, reproducible selection rule, not hand-picked for effect).
candidate_days <- odell_full |>
  mutate(yr = as.integer(format(date, "%Y"))) |>
  filter(yr >= 1989, yr <= 2019, weekdays(date) == "Wednesday") |>
  distinct(date, yr) |>
  group_by(yr) |>
  summarise(date = min(date), .groups = "drop") |>
  pull(date)

cat(sprintf("Testing %d days (one per year, 1989-2019, first Wednesday sitting day)\n\n", length(candidate_days)))

results <- lapply(candidate_days, function(d) {
  od <- odell_full |> filter(date == d)
  ps <- parl_full  |> filter(date == d)
  if (nrow(ps) == 0 || nrow(od) == 0) return(NULL)

  od_speech <- od |> filter(speech_class == "Speech") |> mutate(fp = fingerprint(speech))
  ps2 <- ps |> mutate(fp = fingerprint(text))
  matched <- ps2$fp %in% od_speech$fp
  extra <- ps2 |> filter(!matched)

  missing_debates <- if (nrow(extra) > 0) {
    extra_agendas <- unique(extra$agenda)
    od_headings <- unique(str_trim(od$major_heading))
    # A ParlSpeech agenda title with NO match anywhere in Odell's headings for
    # that day = a debate Odell doesn't have at all (not just mis-fingerprinted)
    sum(!extra_agendas %in% od_headings) # count of wholly-missing debate topics
  } else 0

  tibble(date = d, odell_speech_n = nrow(od_speech), parlspeech_n = nrow(ps2),
         matched_n = sum(matched), extra_n = nrow(extra),
         extra_pct = round(100 * nrow(extra) / nrow(ps2), 1),
         missing_debate_topics = missing_debates)
}) |> bind_rows()

cat("=== Per-day results ===\n")
print(as.data.frame(results), row.names = FALSE)

cat(sprintf("\n=== SUMMARY across %d days ===\n", nrow(results)))
cat(sprintf("Median extra-row rate: %.1f%% (range %.1f%%-%.1f%%)\n",
            median(results$extra_pct), min(results$extra_pct), max(results$extra_pct)))
cat(sprintf("Days with at least one wholly-missing debate topic in Odell: %d of %d\n",
            sum(results$missing_debate_topics > 0), nrow(results)))
cat(sprintf("Total wholly-missing debate topics found: %d\n", sum(results$missing_debate_topics)))
